const e='---\ntitle: "Does SeaMeet AI Note Taker Support In-Person Meetings and Speaker Identification?"\ndescription: "You can use a computer to open Google Meet for meeting recording during in-person meetings with SeaMeet AI Note Taker. However, features like chang..."\ndate: 2025-08-18\nlastmod: 2025-08-18\ndraft: false\nurl: "/faq/does-seameet-ai-note-taker-support-in-person-meetings-and-speaker-identification/"\nslug: "does-seameet-ai-note-taker-support-in-person-meetings-and-speaker-identification"\nmeta_title: "Does SeaMeet AI Note Taker Support In-Person Meetings and Speaker Identification? | SeaMeet FAQ"\nmeta_description: "You can use a computer to open Google Meet for meeting recording during in-person meetings with SeaMeet AI Note Taker. However, features like chang..."\nkeywords: ["seameet","ai","meeting","transcription","meetings","person","speaker","note","taker","support"]\nauthor: "SeaMeet Team"\ncanonical: "/faq/does-seameet-ai-note-taker-support-in-person-meetings-and-speaker-identification/"\nrobots: "index, follow"\nschema_faq:\n  "@context": "https://schema.org"\n  "@type": "FAQPage"\n  "mainEntity":\n    - "@type": "Question"\n      "name": "Does SeaMeet AI Note Taker Support In-Person Meetings and Speaker Identification?"\n      "acceptedAnswer":\n        "@type": "Answer"\n        "text": "You can use a computer to open Google Meet for meeting recording during in-person meetings with SeaMeet AI Note Taker. However, features like changing the speaker for in-person meetings are not yet available and are expected to be provided in Q1 SeaMeet\'s Speaker ID feature helps identify different speakers in recorded meetings, but manual speaker assignment for in-person meetings is coming soon."\n---\n\n# Does SeaMeet AI Note Taker Support In-Person Meetings and Speaker Identification?\n\n## Answer\n\nYou can use a computer to open Google Meet for meeting recording during in-person meetings with SeaMeet AI Note Taker. However, features like changing the speaker for in-person meetings are not yet available and are expected to be provided in Q1 SeaMeet\'s Speaker ID feature helps identify different speakers in recorded meetings, but manual speaker assignment for in-person meetings is coming soon.\n\n---\n\n*Need more help? Contact our support team at seameet@seasalt.ai*\n';export{e as default};
